-- Starsign schema v0.1.0 — generated by hand to match packages/db/src/schema.ts
CREATE EXTENSION IF NOT EXISTS vector;

CREATE TABLE IF NOT EXISTS workspaces (
  id text PRIMARY KEY,
  slug text NOT NULL UNIQUE,
  name text NOT NULL,
  profile jsonb NOT NULL DEFAULT '{}'::jsonb,
  settings jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS users (
  id text PRIMARY KEY,
  email text NOT NULL UNIQUE,
  name text,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS members (
  id text PRIMARY KEY,
  workspace_id text NOT NULL REFERENCES workspaces(id),
  user_id text NOT NULL REFERENCES users(id),
  role text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS members_ws_user ON members(workspace_id, user_id);

CREATE TABLE IF NOT EXISTS api_keys (
  id text PRIMARY KEY,
  workspace_id text NOT NULL REFERENCES workspaces(id),
  key_hash text NOT NULL UNIQUE,
  name text NOT NULL,
  actor_type text NOT NULL,
  actor_id text NOT NULL,
  role text,
  last_used_at timestamptz,
  revoked_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS api_keys_ws ON api_keys(workspace_id);

CREATE TABLE IF NOT EXISTS social_accounts (
  id text PRIMARY KEY,
  workspace_id text NOT NULL REFERENCES workspaces(id),
  network text NOT NULL,
  external_id text NOT NULL,
  handle text NOT NULL,
  display_name text,
  connector text NOT NULL,
  auth_ciphertext text,
  status text NOT NULL DEFAULT 'active',
  config jsonb NOT NULL DEFAULT '{}'::jsonb,
  last_ingest_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS social_accounts_ws_net_ext ON social_accounts(workspace_id, network, external_id);

CREATE TABLE IF NOT EXISTS policies (
  id text PRIMARY KEY,
  workspace_id text NOT NULL REFERENCES workspaces(id),
  version integer NOT NULL,
  document jsonb NOT NULL,
  active boolean NOT NULL DEFAULT true,
  created_by jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS policies_ws_version ON policies(workspace_id, version);

CREATE TABLE IF NOT EXISTS policy_decisions (
  id text PRIMARY KEY,
  workspace_id text NOT NULL REFERENCES workspaces(id),
  policy_version integer NOT NULL,
  subject_type text NOT NULL,
  subject_id text NOT NULL,
  verdict text NOT NULL,
  violations jsonb NOT NULL DEFAULT '[]'::jsonb,
  actor jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS policy_decisions_subject ON policy_decisions(subject_type, subject_id);

CREATE TABLE IF NOT EXISTS posts (
  id text PRIMARY KEY,
  workspace_id text NOT NULL REFERENCES workspaces(id),
  status text NOT NULL,
  title text,
  body text NOT NULL,
  media jsonb NOT NULL DEFAULT '[]'::jsonb,
  scheduled_at timestamptz,
  published_at timestamptz,
  action_class text NOT NULL DEFAULT 'new_post',
  created_by jsonb NOT NULL,
  trend_topic_id text,
  trend_stage_at_creation text,
  trend_forecast_id text,
  experiment_id text,
  experiment_arm text,
  disclosure jsonb,
  evidence jsonb NOT NULL DEFAULT '[]'::jsonb,
  policy_decision jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS posts_ws_status ON posts(workspace_id, status);
CREATE INDEX IF NOT EXISTS posts_ws_sched ON posts(workspace_id, scheduled_at);

CREATE TABLE IF NOT EXISTS post_variants (
  id text PRIMARY KEY,
  post_id text NOT NULL REFERENCES posts(id),
  social_account_id text NOT NULL REFERENCES social_accounts(id),
  network text NOT NULL,
  text text NOT NULL,
  media jsonb NOT NULL DEFAULT '[]'::jsonb,
  thread jsonb NOT NULL DEFAULT '[]'::jsonb,
  status text NOT NULL DEFAULT 'pending',
  external_id text,
  external_url text,
  published_at timestamptz,
  error text,
  attempt_count integer NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS post_variants_post ON post_variants(post_id);
CREATE INDEX IF NOT EXISTS post_variants_account ON post_variants(social_account_id);

CREATE TABLE IF NOT EXISTS approvals (
  id text PRIMARY KEY,
  post_id text NOT NULL REFERENCES posts(id),
  workspace_id text NOT NULL REFERENCES workspaces(id),
  state text NOT NULL,
  requested_by jsonb NOT NULL,
  decided_by jsonb,
  decided_at timestamptz,
  note text,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS approvals_post ON approvals(post_id);
CREATE INDEX IF NOT EXISTS approvals_ws_state ON approvals(workspace_id, state);

CREATE TABLE IF NOT EXISTS approval_diffs (
  id text PRIMARY KEY,
  workspace_id text NOT NULL REFERENCES workspaces(id),
  post_id text NOT NULL REFERENCES posts(id),
  variant_id text REFERENCES post_variants(id),
  before_text text NOT NULL,
  after_text text NOT NULL,
  drafted_by jsonb NOT NULL,
  edited_by jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS approval_diffs_ws ON approval_diffs(workspace_id);

CREATE TABLE IF NOT EXISTS experiments (
  id text PRIMARY KEY,
  workspace_id text NOT NULL REFERENCES workspaces(id),
  name text NOT NULL,
  hypothesis text NOT NULL,
  status text NOT NULL DEFAULT 'draft',
  arms jsonb NOT NULL DEFAULT '[]'::jsonb,
  primary_metric text NOT NULL DEFAULT 'engagements',
  result jsonb,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS streams (
  id text PRIMARY KEY,
  workspace_id text NOT NULL REFERENCES workspaces(id),
  name text NOT NULL,
  query jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS activities (
  id text PRIMARY KEY,
  workspace_id text NOT NULL REFERENCES workspaces(id),
  social_account_id text REFERENCES social_accounts(id),
  network text NOT NULL,
  kind text NOT NULL,
  external_id text NOT NULL,
  author_handle text,
  author_name text,
  text text,
  url text,
  parent_external_id text,
  occurred_at timestamptz NOT NULL,
  ingested_at timestamptz NOT NULL DEFAULT now(),
  sentiment double precision,
  matched_streams jsonb NOT NULL DEFAULT '[]'::jsonb,
  raw_event_id text
);
CREATE UNIQUE INDEX IF NOT EXISTS activities_ws_net_ext ON activities(workspace_id, network, external_id);
CREATE INDEX IF NOT EXISTS activities_ws_time ON activities(workspace_id, occurred_at);

CREATE TABLE IF NOT EXISTS metrics (
  entity_type text NOT NULL,
  entity_id text NOT NULL,
  metric text NOT NULL,
  value double precision NOT NULL,
  observed_at timestamptz NOT NULL,
  source text NOT NULL
);
CREATE INDEX IF NOT EXISTS metrics_entity_time ON metrics(entity_type, entity_id, metric, observed_at);

CREATE TABLE IF NOT EXISTS post_outcomes (
  id text PRIMARY KEY,
  workspace_id text NOT NULL REFERENCES workspaces(id),
  post_id text NOT NULL REFERENCES posts(id),
  variant_id text NOT NULL REFERENCES post_variants(id),
  offset_label text NOT NULL,
  due_at timestamptz NOT NULL,
  captured_at timestamptz,
  metrics jsonb,
  status text NOT NULL DEFAULT 'due'
);
CREATE UNIQUE INDEX IF NOT EXISTS post_outcomes_variant_offset ON post_outcomes(variant_id, offset_label);
CREATE INDEX IF NOT EXISTS post_outcomes_due ON post_outcomes(status, due_at);

CREATE TABLE IF NOT EXISTS trend_topics (
  id text PRIMARY KEY,
  workspace_id text REFERENCES workspaces(id),
  name text NOT NULL,
  keywords jsonb NOT NULL DEFAULT '[]'::jsonb,
  relevance double precision,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS trend_topics_ws ON trend_topics(workspace_id);

CREATE TABLE IF NOT EXISTS trend_points (
  topic_id text NOT NULL REFERENCES trend_topics(id),
  source text NOT NULL,
  region text NOT NULL DEFAULT 'global',
  value double precision NOT NULL,
  observed_at timestamptz NOT NULL
);
CREATE INDEX IF NOT EXISTS trend_points_topic_time ON trend_points(topic_id, source, observed_at);

CREATE TABLE IF NOT EXISTS trend_forecasts (
  id text PRIMARY KEY,
  topic_id text NOT NULL REFERENCES trend_topics(id),
  computed_at timestamptz NOT NULL DEFAULT now(),
  stage text NOT NULL,
  confidence double precision NOT NULL,
  velocity double precision NOT NULL,
  acceleration double precision NOT NULL,
  hours_to_peak double precision,
  horizon_hours integer NOT NULL,
  curve jsonb NOT NULL,
  model_version text NOT NULL,
  source_agreement double precision,
  sources jsonb NOT NULL DEFAULT '[]'::jsonb
);
CREATE INDEX IF NOT EXISTS trend_forecasts_topic_time ON trend_forecasts(topic_id, computed_at);

CREATE TABLE IF NOT EXISTS trend_actions (
  id text PRIMARY KEY,
  workspace_id text NOT NULL REFERENCES workspaces(id),
  post_id text NOT NULL REFERENCES posts(id),
  topic_id text NOT NULL REFERENCES trend_topics(id),
  stage_at_action text NOT NULL,
  forecast_id text,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS trend_actions_topic ON trend_actions(topic_id);
CREATE INDEX IF NOT EXISTS trend_actions_ws ON trend_actions(workspace_id);

CREATE TABLE IF NOT EXISTS embeddings (
  entity_type text NOT NULL,
  entity_id text NOT NULL,
  model text NOT NULL,
  embedding vector(1024) NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (entity_type, entity_id, model)
);

-- Append-only logs ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS raw_events (
  id text PRIMARY KEY,
  seq bigserial NOT NULL,
  source text NOT NULL,
  kind text NOT NULL,
  workspace_id text,
  external_id text,
  received_at timestamptz NOT NULL DEFAULT now(),
  payload jsonb NOT NULL,
  hash text NOT NULL
);
CREATE INDEX IF NOT EXISTS raw_events_source_time ON raw_events(source, received_at);
CREATE INDEX IF NOT EXISTS raw_events_hash ON raw_events(hash);

CREATE TABLE IF NOT EXISTS ledger_events (
  id text PRIMARY KEY,
  seq bigserial NOT NULL,
  workspace_id text NOT NULL,
  type text NOT NULL,
  subject_type text NOT NULL,
  subject_id text NOT NULL,
  actor jsonb NOT NULL,
  data jsonb NOT NULL DEFAULT '{}'::jsonb,
  occurred_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS ledger_ws_time ON ledger_events(workspace_id, occurred_at);
CREATE INDEX IF NOT EXISTS ledger_subject ON ledger_events(subject_type, subject_id);

CREATE OR REPLACE FUNCTION starsign_append_only() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'table % is append-only (Starsign event store)', TG_TABLE_NAME;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS raw_events_append_only ON raw_events;
CREATE TRIGGER raw_events_append_only BEFORE UPDATE OR DELETE ON raw_events
  FOR EACH ROW EXECUTE FUNCTION starsign_append_only();
DROP TRIGGER IF EXISTS ledger_events_append_only ON ledger_events;
CREATE TRIGGER ledger_events_append_only BEFORE UPDATE OR DELETE ON ledger_events
  FOR EACH ROW EXECUTE FUNCTION starsign_append_only();

-- Operators -------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS operator_runs (
  id text PRIMARY KEY,
  workspace_id text NOT NULL REFERENCES workspaces(id),
  operator text NOT NULL,
  started_at timestamptz NOT NULL DEFAULT now(),
  finished_at timestamptz,
  status text NOT NULL DEFAULT 'running',
  summary text,
  input_tokens integer NOT NULL DEFAULT 0,
  output_tokens integer NOT NULL DEFAULT 0,
  cost_usd double precision NOT NULL DEFAULT 0,
  error text
);
CREATE INDEX IF NOT EXISTS operator_runs_ws ON operator_runs(workspace_id, started_at);

CREATE TABLE IF NOT EXISTS briefs (
  id text PRIMARY KEY,
  workspace_id text NOT NULL REFERENCES workspaces(id),
  period_start timestamptz NOT NULL,
  period_end timestamptz NOT NULL,
  content_md text NOT NULL,
  evidence jsonb NOT NULL DEFAULT '[]'::jsonb,
  run_id text,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS alerts (
  id text PRIMARY KEY,
  workspace_id text NOT NULL REFERENCES workspaces(id),
  kind text NOT NULL,
  severity text NOT NULL DEFAULT 'attention',
  title text NOT NULL,
  body text NOT NULL,
  evidence jsonb NOT NULL DEFAULT '[]'::jsonb,
  topic_id text,
  acknowledged_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS alerts_ws ON alerts(workspace_id, created_at);

-- TimescaleDB, when available: metrics and trend_points become hypertables.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_available_extensions WHERE name = 'timescaledb') THEN
    EXECUTE 'CREATE EXTENSION IF NOT EXISTS timescaledb';
    PERFORM create_hypertable('metrics', 'observed_at', if_not_exists => TRUE, migrate_data => TRUE);
    PERFORM create_hypertable('trend_points', 'observed_at', if_not_exists => TRUE, migrate_data => TRUE);
  END IF;
END $$;
